import json,os,sys,urllib.request,urllib.parse
keys=[k.strip() for k in os.environ['OPENALEX_API_KEYS'].split(',') if k.strip()]
def get(u):
    for k in keys:
        try:
            d=json.load(urllib.request.urlopen(u+('&' if '?' in u else '?')+'api_key='+k,timeout=60))
            return d
        except urllib.error.HTTPError as e:
            if e.code==404: return None
    return None
for doi in sys.argv[1:]:
    w=get('https://api.openalex.org/works/doi:'+urllib.parse.quote(doi,safe='/()<>:;'))
    if not w: print(doi,'NOTFOUND\n'); continue
    inv=w.get('abstract_inverted_index') or {}
    pos=sorted((p,t) for t,ps in inv.items() for p in ps)
    print(doi,'|',w['title'],'|',w['publication_year']); print(' '.join(t for p,t in pos) or '[no abstract]'); print()
EOF
